    'dl.version': 'Version {v}', 'dl.updated': 'Aktualisiert am {d}', 'unit.gb': 'GB', 'unit.mb': 'MB',
    'dl.c1.h': '💻 Systemanforderungen', 'dl.c1.p': 'Windows 10 oder 11, 64 Bit. 2 GB RAM, 1 GB Speicherplatz.', 'dl.c1.pMac': 'Windows 10 oder 11 (64 Bit) oder macOS 12 und neuer (Mac mit Intel- oder Apple-Chip). 2 GB RAM, 1 GB Speicherplatz.',
    'dl.c2.h': '👥 Mehrere Accounts', 'dl.c2.p': 'Markiere mehrere Accounts im Launcher: für jeden öffnet sich ein Client.',
    'dl.c3.h': '🌍 6 Sprachen', 'dl.c3.p': 'Der Launcher spricht Französisch, Englisch, Spanisch, Deutsch, Italienisch und Portugiesisch.',
    'dl.btnMac': '⬇ Für Mac herunterladen', 'dl.macSoon': 'Mac: bald verfügbar', 'dl.otherOs': 'Anderes System:', 'dl.installMac': 'Installation auf dem Mac', 'dl.installWin': 'Installation unter Windows',
    'dl.m1': 'Lade das <strong>.zip</strong>-Archiv herunter: Safari entpackt es automatisch (sonst doppelklicken). Ziehe <strong>Draco</strong> in deinen Ordner <strong>Programme</strong>.',
    'dl.m2': 'Öffne <strong>Draco</strong>. Beim ersten Mal meldet macOS „Apple konnte nicht überprüfen …“: schließe die Meldung, öffne <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit</strong>, scrolle zu „Draco wurde blockiert“ und klicke auf <em>Dennoch öffnen</em> (nur einmal).',
